<?php
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/koneksi.php';require_admin();$pageTitle='Laporan';
$type=$_GET['jenis']??'siswa';$valid=['siswa','absensi','monitoring'];if(!in_array($type,$valid,true))$type='siswa';
if($type==='siswa'){$title='Laporan Data Siswa PKL';$rows=$pdo->query("SELECT s.nis,s.nama,s.kelas,s.jurusan,pr.nama perusahaan,b.nama pembimbing,p.tanggal_mulai,p.tanggal_selesai,p.status FROM siswa s LEFT JOIN penempatan p ON p.siswa_id=s.id LEFT JOIN perusahaan pr ON pr.id=p.perusahaan_id LEFT JOIN pembimbing b ON b.id=p.pembimbing_id ORDER BY s.nama")->fetchAll();}
elseif($type==='absensi'){$title='Laporan Kehadiran';$rows=$pdo->query("SELECT s.nis,s.nama,COUNT(a.id) total,SUM(a.status='Hadir') hadir,SUM(a.status='Izin') izin,SUM(a.status='Sakit') sakit,SUM(a.status='Alpa') alpa,ROUND(COALESCE(SUM(a.status='Hadir')/NULLIF(COUNT(a.id),0)*100,0),1) persen FROM siswa s LEFT JOIN absensi a ON a.siswa_id=s.id GROUP BY s.id ORDER BY s.nama")->fetchAll();}
else{$title='Laporan Monitoring';$rows=$pdo->query("SELECT m.tanggal,s.nis,s.nama,m.catatan,m.nilai,m.rekomendasi FROM monitoring m JOIN siswa s ON s.id=m.siswa_id ORDER BY m.tanggal DESC")->fetchAll();}
include __DIR__.'/../partials/header.php';?>
<div class="page-head no-print"><div><h1>Laporan</h1><div class="muted">Pilih laporan, lalu cetak atau simpan sebagai PDF.</div></div><button class="btn" onclick="window.print()">Cetak / Simpan PDF</button></div>
<div class="card no-print"><div class="filters"><?php foreach(['siswa'=>'Data Siswa PKL','absensi'=>'Kehadiran','monitoring'=>'Monitoring'] as $k=>$v):?><a class="btn <?=$type===$k?'':'secondary'?>" href="?jenis=<?=$k?>"><?=e($v)?></a><?php endforeach;?></div></div>
<div class="card"><div class="report-title"><h2>InternTrack — <?=e($title)?></h2><p>Tanggal cetak: <?=date('d-m-Y')?></p></div><h3 class="no-print"><?=e($title)?></h3><div class="table-wrap"><table><thead><tr><?php if($type==='siswa'):?><th>NIS</th><th>Nama</th><th>Kelas</th><th>Jurusan</th><th>Perusahaan</th><th>Pembimbing</th><th>Mulai</th><th>Selesai</th><th>Status</th><?php elseif($type==='absensi'):?><th>NIS</th><th>Nama</th><th>Total Hari</th><th>Hadir</th><th>Izin</th><th>Sakit</th><th>Alpa</th><th>Persentase</th><th>Status</th><?php else:?><th>Tanggal</th><th>NIS</th><th>Nama</th><th>Catatan</th><th>Nilai</th><th>Rekomendasi</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($type==='siswa'):?><td><?=e($r['nis'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['kelas'])?></td><td><?=e($r['jurusan'])?></td><td><?=e($r['perusahaan']??'-')?></td><td><?=e($r['pembimbing']??'-')?></td><td><?=e($r['tanggal_mulai']??'-')?></td><td><?=e($r['tanggal_selesai']??'-')?></td><td><?=e($r['status']??'Belum ditempatkan')?></td><?php elseif($type==='absensi'):?><td><?=e($r['nis'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['total']??0)?></td><td><?=e($r['hadir']??0)?></td><td><?=e($r['izin']??0)?></td><td><?=e($r['sakit']??0)?></td><td><?=e($r['alpa']??0)?></td><td><?=e($r['persen'])?>%</td><td><?=e(status_pkl((float)$r['persen']))?></td><?php else:?><td><?=e($r['tanggal'])?></td><td><?=e($r['nis'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['catatan'])?></td><td><?=e($r['nilai'])?></td><td><?=e($r['rekomendasi'])?></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="10" class="empty">Belum ada data untuk laporan ini.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../partials/footer.php';?>
